CREATE OR REPLACE PACKAGE BODY ut_pell_examples AS
  TYPE t_text_list IS TABLE OF VARCHAR2(4000) INDEX BY PLS_INTEGER;

  PROCEDURE suite_setup IS
    l_accounts NUMBER;
  BEGIN
    BEGIN
      select count(*)
      INTO l_accounts
      FROM billing.accounts;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    logger.info(('ut_pell_examples: suite starting — ' || TO_CHAR(l_accounts) || ' billing account(s)'));
  END suite_setup;

  PROCEDURE suite_teardown IS
  BEGIN
    logger.info('ut_pell_examples: suite complete');
  END suite_teardown;

  PROCEDURE t_greet IS
  BEGIN
    ut.expect(hello.greet('world')).to_equal('hello, world');
  END t_greet;

  PROCEDURE t_text_utils IS
    l_parts text_utils.t_text_list;
    l_lit_join VARCHAR2(4000);
    l_pell_arg_1 text_utils.t_text_list;
    l_grown t_text_list;
    l_grown_line VARCHAR2(4000);
    l_pell_arg_2 data.csv.t_text_list;
  BEGIN
    ut.expect(text_utils.len('abc')).to_equal(3);
    ut.expect(text_utils.trim_ws('  x  ')).to_equal('x');
    ut.expect(text_utils.to_upper('abc')).to_equal('ABC');
    ut.expect(text_utils.has('haystack', 'hay')).to_be_true();
    ut.expect(text_utils.is_blank('   ')).to_be_true();
    ut.expect(text_utils.is_blank('x')).to_be_false();
    ut.expect(text_utils.index_of('hello', 'll')).to_equal(3);
    ut.expect(text_utils.before('key=value', '=')).to_equal('key');
    ut.expect(text_utils.after('key=value', '=')).to_equal('value');
    ut.expect(text_utils.text_between('x[mid]y', '[', ']')).to_equal('mid');
    ut.expect(text_utils.strip_prefix('pre_x', 'pre_')).to_equal('x');
    ut.expect(text_utils.strip_suffix('x.sql', '.sql')).to_equal('x');
    ut.expect(text_utils.repeat_text('ab', 3)).to_equal('ababab');
    ut.expect(text_utils.ellipsize('abcdefghij', 8)).to_equal('abcde...');
    ut.expect(text_utils.squish('  a   b  ')).to_equal('a b');
    ut.expect(text_utils.title_case('hello world')).to_equal('Hello World');
    ut.expect(text_utils.default_if_blank('  ', 'dflt')).to_equal('dflt');
    ut.expect(text_utils.camel_to_snake('userName')).to_equal('user_name');
    ut.expect(text_utils.snake_to_camel('user_name')).to_equal('UserName');
    l_parts := text_utils.split('a-b-c', '-');
    ut.expect(text_utils.join(l_parts, '+')).to_equal('a+b+c');
    l_pell_arg_1(1) := 'x';
    l_pell_arg_1(2) := 'y';
    l_pell_arg_1(3) := 'z';
    l_lit_join := text_utils.join(l_pell_arg_1, '-');
    ut.expect(l_lit_join).to_equal('x-y-z');
    l_grown(l_grown.COUNT + 1) := 'a';
    l_grown(l_grown.COUNT + 1) := 'b';
    IF l_grown.COUNT > 0 THEN
      FOR i_2 IN 1 .. l_grown.COUNT LOOP
        l_pell_arg_2(i_2) := l_grown(i_2);
      END LOOP;
    END IF;
    l_grown_line := data.csv.to_line(l_pell_arg_2);
    ut.expect(l_grown_line).to_equal('a,b');
  END t_text_utils;

  PROCEDURE t_json_roundtrip IS
    l_j JSON;
    l_n JSON;
  BEGIN
    l_j := json_demo.build_simple();
    ut.expect(JSON_VALUE(l_j, '$.name')).to_equal('Alice');
    ut.expect(JSON_VALUE(l_j, '$.age' RETURNING NUMBER)).to_equal(30);
    l_n := json_demo.build_nested();
    ut.expect(JSON_VALUE(l_n, '$.user.address.city')).to_equal('NYC');
    ut.expect(json_demo.extract_text(l_n, '$.user.name')).to_equal('Bob');
    ut.expect(json_demo.has_path(l_n, '$.meta.created')).to_be_true();
    ut.expect(json_demo.has_path(l_n, '$.meta.missing')).to_be_false();
  END t_json_roundtrip;

  PROCEDURE t_linked_list IS
    l_l t_intlist;
    l_s collections_linked_list.t_summary;
    l_r t_intlist;
    l_s2 collections_linked_list.t_summary;
  BEGIN
    l_l := collections_linked_list.cons(3, collections_linked_list.cons(1, collections_linked_list.cons(7, collections_linked_list.nil())));
    l_s := collections_linked_list.summarize(l_l);
    ut.expect(l_s.total).to_equal(11);
    ut.expect(l_s.count).to_equal(3);
    l_r := collections_linked_list.reversed(l_l);
    l_s2 := collections_linked_list.summarize(l_r);
    ut.expect(l_s2.total).to_equal(11);
    ut.expect(l_s2.count).to_equal(3);
  END t_linked_list;

  PROCEDURE t_staffing IS
    l_e hr.staffing.t_employee;
    l_e2 hr.staffing.t_employee;
  BEGIN
    delete from hr.employees where id = 9001;
    insert into hr.employees(id, name, email, grade)
               values (9001, 'Test Person', 't@example.com', 3);
    l_e := hr.staffing.find_employee(9001);
    ut.expect(l_e.name).to_equal('Test Person');
    hr.staffing.promote(9001);
    l_e2 := hr.staffing.find_employee(9001);
    ut.expect(l_e2.grade).to_equal(4);
    delete from hr.employees where id = 9001;
  END t_staffing;

  PROCEDURE t_stock IS
    l_id NUMBER;
    l_qty NUMBER;
  BEGIN
    l_id := inventory.stock.create_sku('UT-TEST-1', 5);
    ut.expect(l_id).to_be_not_null();
    BEGIN
      select qty
      INTO l_qty
      FROM inventory.skus where id = l_id;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_qty).to_equal(5);
    delete from inventory.skus where id = l_id;
  END t_stock;

  PROCEDURE t_mermaid IS
    l_d VARCHAR2(4000);
  BEGIN
    l_d := ((mermaid.flowchart('TD') || mermaid.node('a', 'Start')) || mermaid.link('a', 'a'));
    ut.expect(l_d).to_be_like('flowchart TD%a["Start"]%a --> a%');
    ut.expect(mermaid.esc('say "hi" [now]')).to_equal('say ''hi'' (now)');
    ut.expect(mermaid.fence('x')).to_be_like('```mermaid%x%```');
  END t_mermaid;

  PROCEDURE t_explain_op IS
  BEGIN
    ut.expect(explain_plan.explain_op('TABLE ACCESS', 'FULL')).to_be_like('%full scan%');
    ut.expect(explain_plan.explain_op('INDEX', 'UNIQUE SCAN')).to_be_like('%unique index%');
