  END t_explain_op;

  PROCEDURE t_stat_diff IS
    l_before JSON;
    l_after JSON;
    l_r VARCHAR2(4000);
  BEGIN
    l_before := stat_diff.snapshot();
    ut.expect(JSON_VALUE(l_before, '$.logical_reads' RETURNING NUMBER)).to_be_not_null();
    ut.expect(JSON_VALUE(l_before, '$.consistent_gets' RETURNING NUMBER)).to_be_not_null();
    l_after := stat_diff.snapshot();
    l_r := stat_diff.report(l_before, l_after);
    ut.expect(l_r).to_be_like('%statistic%before%after%delta%');
  END t_stat_diff;

  PROCEDURE setup_transfer IS
  BEGIN
    DECLARE
      l_committed_0 BOOLEAN := FALSE;
    BEGIN
      SAVEPOINT pell_sp_0;  -- @ 36_ut_examples.pell:205
      delete from billing.accounts where id in (9101, 9102);
      insert into billing.accounts(id, balance, frozen) values (9101, 100, 0);
      insert into billing.accounts(id, balance, frozen) values (9102, 10, 0);
      COMMIT;
      l_committed_0 := TRUE;
    EXCEPTION
      WHEN OTHERS THEN
        IF NOT l_committed_0 THEN ROLLBACK TO pell_sp_0; END IF;  -- @ 36_ut_examples.pell:205
        RAISE;
    END;
  END setup_transfer;

  PROCEDURE teardown_transfer IS
  BEGIN
    DECLARE
      l_committed_0 BOOLEAN := FALSE;
    BEGIN
      SAVEPOINT pell_sp_0;  -- @ 36_ut_examples.pell:213
      delete from billing.accounts where id in (9101, 9102);
      COMMIT;
      l_committed_0 := TRUE;
    EXCEPTION
      WHEN OTHERS THEN
        IF NOT l_committed_0 THEN ROLLBACK TO pell_sp_0; END IF;  -- @ 36_ut_examples.pell:213
        RAISE;
    END;
  END teardown_transfer;

  PROCEDURE t_transfer IS
    l_xfer billing.charges.t_transfer;
    l_b1 NUMBER;
    l_b2 NUMBER;
  BEGIN
    l_xfer.from_id := 9101;
    l_xfer.to_id := 9102;
    l_xfer.amt := 40;
    billing.charges.transfer(l_xfer);
    BEGIN
      select balance
      INTO l_b1
      FROM billing.accounts where id = 9101;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    BEGIN
      select balance
      INTO l_b2
      FROM billing.accounts where id = 9102;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_b1).to_equal(60);
    ut.expect(l_b2).to_equal(50);
  END t_transfer;

  PROCEDURE t_daily IS
