    reports.daily.print_recent(std.datetime.add_days(std.datetime.today(), -1));
    ut.expect(1).to_equal(1);
    delete from reports.orders where order_id = 9111;
  END t_daily;

  PROCEDURE t_country IS
  BEGIN
    delete from lookups.countries where code = 'ZZ';
    insert into lookups.countries(code, name) values ('ZZ', 'Testland');
    ut.expect(lookups.country.country_name('ZZ')).to_equal('Testland');
    lookups.country.audit_log('ut probe');
    delete from lookups.countries where code = 'ZZ';
  END t_country;

  PROCEDURE t_fulfillment IS
    l_o orders.fulfillment.t_order;
    l_line_id NUMBER;
    l_qty NUMBER;
  BEGIN
    delete from orders.order_lines where order_id = 9201;
    delete from orders.orders where id = 9201;
    delete from orders.skus where id = 9301;
    insert into orders.orders(id, customer_id, status, total, created_at)
               values (9201, 1, 'NEW', 0, sysdate);
    insert into orders.skus(id, qty) values (9301, 10);
    l_o := orders.fulfillment.fetch_order(9201);
    ut.expect(l_o.status).to_equal('NEW');
    l_line_id := orders.fulfillment.add_line(9201, 9301, 2);
    ut.expect(l_line_id).to_be_not_null();
    ut.expect(orders.fulfillment.count_lines(9201)).to_equal(1);
    BEGIN
      select qty
      INTO l_qty
      FROM orders.skus where id = 9301;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_qty).to_equal(8);
    delete from orders.order_lines where order_id = 9201;
    delete from orders.orders where id = 9201;
    delete from orders.skus where id = 9301;
  END t_fulfillment;

