    ut.expect(l_kv.v).to_equal('blue');
    l_e := re_capture_demo.parse_email('joe@example.com');
    ut.expect(l_e.user).to_equal('joe');
    ut.expect(l_e.domain).to_equal('example.com');
  END t_re_capture;

  PROCEDURE t_datetime IS
    l_ts TIMESTAMP;
    l_feb TIMESTAMP;
    l_jan31 TIMESTAMP;
  BEGIN
    ut.expect(std.datetime.now()).to_be_not_null();
    ut.expect(std.datetime.days_between(std.datetime.today(), std.datetime.add_days(std.datetime.today(), 3))).to_equal(3);
    l_ts := std.datetime.parse_iso('2026-06-13T12:00:00');
    ut.expect(std.datetime.format_iso(l_ts)).to_be_like('2026-06-13T12:00:00%');
    ut.expect(std.datetime.epoch(std.datetime.from_epoch(1750000000))).to_equal(1750000000);
    l_feb := std.datetime.parse_iso('2026-02-14T15:30:00');
    ut.expect(std.datetime.format_iso(std.datetime.start_of_day(l_feb))).to_be_like('2026-02-14T00:00:00%');
    ut.expect(std.datetime.format_iso(std.datetime.start_of_month(l_feb))).to_be_like('2026-02-01%');
    ut.expect(std.datetime.format_iso(std.datetime.end_of_month(l_feb))).to_be_like('2026-02-28%');
    ut.expect(std.datetime.format_iso(std.datetime.start_of_week(l_feb))).to_be_like('2026-02-09%');
    ut.expect(std.datetime.day_of_week(l_feb)).to_equal(6);
    ut.expect(std.datetime.day_name(l_feb)).to_equal('Saturday');
    ut.expect(std.datetime.is_weekend(l_feb)).to_be_true();
    ut.expect(std.datetime.year_of(l_feb)).to_equal(2026);
    ut.expect(std.datetime.month_of(l_feb)).to_equal(2);
    ut.expect(std.datetime.day_of(l_feb)).to_equal(14);
    ut.expect(std.datetime.hour_of(l_feb)).to_equal(15);
    ut.expect(std.datetime.days_in_month(l_feb)).to_equal(28);
    ut.expect(std.datetime.is_leap_year(l_feb)).to_be_false();
    ut.expect(std.datetime.is_leap_year(std.datetime.parse_iso('2028-06-01T00:00:00'))).to_be_true();
    l_jan31 := std.datetime.parse_iso('2026-01-31T00:00:00');
    ut.expect(std.datetime.format_iso(std.datetime.add_months_to(l_jan31, 1))).to_be_like('2026-02-28%');
  END t_datetime;

  PROCEDURE t_validation IS
    l_t VARCHAR2(4000);
    l_e VARCHAR2(4000);
    l_a NUMBER;
    l_sf signups.validation.t_signupform;
    l_form signups.validation.t_signupform;
    l_ml VARCHAR2(4000);
    l_xl VARCHAR2(4000);
    l_rng NUMBER;
    l_pat VARCHAR2(4000);
    l_one VARCHAR2(4000);
  BEGIN
    l_t := signups.validation.require_text('name', 'Ann');
    ut.expect(l_t).to_equal('Ann');
    l_e := signups.validation.require_email('ann@example.com');
    ut.expect(l_e).to_equal('ann@example.com');
    l_a := signups.validation.require_age(30);
    ut.expect(l_a).to_equal(30);
    l_sf.name := 'Ann';
    l_sf.email := 'ann@example.com';
    l_sf.age := 30;
    l_form := signups.validation.validate_signup(l_sf);
    ut.expect(l_form.name).to_equal('Ann');
    l_ml := signups.validation.require_min_length('pw', 'secret12', 8);
    ut.expect(l_ml).to_equal('secret12');
    l_xl := signups.validation.require_max_length('code', 'abc', 5);
    ut.expect(l_xl).to_equal('abc');
    l_rng := signups.validation.require_in_range('qty', 5, 1, 10);
    ut.expect(l_rng).to_equal(5);
    l_pat := signups.validation.require_pattern('zip', '90210', '^\d{5}$');
    ut.expect(l_pat).to_equal('90210');
    l_one := signups.validation.require_one_of('size', 'M', 'S,M,L,XL');
    ut.expect(l_one).to_equal('M');
  END t_validation;

  PROCEDURE t_paging IS
    l_pg orders.paging.t_Order_list;
  BEGIN
    delete from orders.orders where status = 'UTP';
    insert into orders.orders(id, customer_id, status, total, created_at)
               values (9501, 1, 'UTP', 1, sysdate);
    insert into orders.orders(id, customer_id, status, total, created_at)
               values (9502, 1, 'UTP', 2, sysdate);
    insert into orders.orders(id, customer_id, status, total, created_at)
               values (9503, 1, 'UTP', 3, sysdate);
    ut.expect(orders.paging.count_matching('UTP')).to_equal(3);
    ut.expect(orders.paging.page_count(3, 2)).to_equal(2);
    ut.expect(orders.paging.has_next_page(1, 2, 3)).to_be_true();
    ut.expect(orders.paging.has_next_page(2, 2, 3)).to_be_false();
    l_pg := orders.paging.page_of('UTP', 1, 2);
    ut.expect(l_pg.COUNT).to_equal(2);
    delete from orders.orders where status = 'UTP';
  END t_paging;

  PROCEDURE t_csv IS
    l_cells data.csv.t_text_list;
    l_p JSON;
    l_h JSON;
    l_rt JSON;
    l_line VARCHAR2(4000);
  BEGIN
    l_cells := data.csv.parse_line('a,"b,c","say ""hi"""');
    ut.expect(l_cells.COUNT).to_equal(3);
    ut.expect(l_cells(2)).to_equal('b,c');
    ut.expect(l_cells(3)).to_equal('say "hi"');
    l_p := data.csv.parse('a,b,c,d,e' || CHR(13) || '
x,"y
y",z
');
    ut.expect(data.csv.row_count(l_p)).to_equal(2);
    ut.expect(data.csv.col_count(l_p, 1)).to_equal(5);
    ut.expect(data.csv.col_count(l_p, 2)).to_equal(3);
    ut.expect(data.csv.cell(l_p, 2, 2)).to_equal('y
y');
    l_h := data.csv.parse_with_header('name,age
Ann,34
Bob,55');
    ut.expect(data.csv.row_count(l_h)).to_equal(2);
    ut.expect(data.csv.field(l_h, 2, 'age')).to_equal('55');
    ut.expect(data.csv.quote_field('a,b')).to_equal('"a,b"');
    ut.expect(data.csv.quote_field('plain')).to_equal('plain');
    l_rt := data.csv.parse('a,"b,c"
d,e');
    ut.expect(data.csv.to_csv(l_rt)).to_equal('a,"b,c"
d,e');
    l_line := data.csv.to_line(l_cells);
    ut.expect(l_line).to_equal('a,"b,c","say ""hi"""');
  END t_csv;

  PROCEDURE t_repl_demo IS
    l_emp repl_demo.t_employee;
