  PROCEDURE t_dyn_cursor IS
    l_n NUMBER;
    l_pell_cur_1 SYS_REFCURSOR;
    l_pell_dyn_cur_1 PLS_INTEGER;
    l_pell_col_cnt_1 PLS_INTEGER;
    l_pell_desc_1 DBMS_SQL.DESC_TAB;
    l_pell_idx_1 PLS_INTEGER;
    l_pell_row_1 JSON;
    l_pell_jobj_1 JSON_OBJECT_T;
    l_pell_buf_str_1 VARCHAR2(4000);
    l_pell_buf_num_1 NUMBER;
    l_pell_buf_dt_1 DATE;
    l_pell_buf_ts_1 TIMESTAMP;
    l_pell_col_name_1 VARCHAR2(128);
  BEGIN
    delete from pivot_orders;
    insert into pivot_orders(product, region, sales) values ('ut-x', 'EAST', 5);
    l_n := 0;
    l_pell_cur_1 := dyn_cursor_demo.region_sales();
    l_pell_dyn_cur_1 := DBMS_SQL.TO_CURSOR_NUMBER(l_pell_cur_1);
    DBMS_SQL.DESCRIBE_COLUMNS(l_pell_dyn_cur_1, l_pell_col_cnt_1, l_pell_desc_1);
    FOR l_pell_idx_1 IN 1 .. l_pell_col_cnt_1 LOOP
      IF l_pell_desc_1(l_pell_idx_1).col_type = 2 THEN
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_num_1);
      ELSIF l_pell_desc_1(l_pell_idx_1).col_type = 12 THEN
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_dt_1);
      ELSIF l_pell_desc_1(l_pell_idx_1).col_type IN (180, 181, 231) THEN
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_ts_1);
      ELSE
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_str_1, 4000);
      END IF;
    END LOOP;
    WHILE DBMS_SQL.FETCH_ROWS(l_pell_dyn_cur_1) > 0 LOOP
      l_pell_jobj_1 := NEW JSON_OBJECT_T();
      FOR l_pell_idx_1 IN 1 .. l_pell_col_cnt_1 LOOP
        l_pell_col_name_1 := l_pell_desc_1(l_pell_idx_1).col_name;
        IF l_pell_desc_1(l_pell_idx_1).col_type = 2 THEN
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_num_1);
          IF l_pell_buf_num_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, l_pell_buf_num_1); END IF;
        ELSIF l_pell_desc_1(l_pell_idx_1).col_type = 12 THEN
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_dt_1);
          IF l_pell_buf_dt_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, TO_CHAR(l_pell_buf_dt_1, 'YYYY-MM-DD"T"HH24:MI:SS')); END IF;
        ELSIF l_pell_desc_1(l_pell_idx_1).col_type IN (180, 181, 231) THEN
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_ts_1);
          IF l_pell_buf_ts_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, TO_CHAR(l_pell_buf_ts_1, 'YYYY-MM-DD"T"HH24:MI:SS.FF6')); END IF;
        ELSE
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_str_1);
          IF l_pell_buf_str_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, l_pell_buf_str_1); END IF;
        END IF;
      END LOOP;
      l_pell_row_1 := l_pell_jobj_1.to_json();
      l_n := (l_n + 1);
    END LOOP;
    DBMS_SQL.CLOSE_CURSOR(l_pell_dyn_cur_1);
    ut.expect((l_n > 0)).to_be_true();
    delete from pivot_orders;
  END t_dyn_cursor;

  PROCEDURE t_source_stats IS
    l_saw NUMBER;
    l_pell_cur_1 SYS_REFCURSOR;
    l_pell_dyn_cur_1 PLS_INTEGER;
    l_pell_col_cnt_1 PLS_INTEGER;
    l_pell_desc_1 DBMS_SQL.DESC_TAB;
    l_pell_idx_1 PLS_INTEGER;
    l_pell_row_1 JSON;
    l_pell_jobj_1 JSON_OBJECT_T;
    l_pell_buf_str_1 VARCHAR2(4000);
    l_pell_buf_num_1 NUMBER;
    l_pell_buf_dt_1 DATE;
    l_pell_buf_ts_1 TIMESTAMP;
    l_pell_col_name_1 VARCHAR2(128);
  BEGIN
    l_saw := 0;
    l_pell_cur_1 := source_stats.lines_by_kind();
    l_pell_dyn_cur_1 := DBMS_SQL.TO_CURSOR_NUMBER(l_pell_cur_1);
    DBMS_SQL.DESCRIBE_COLUMNS(l_pell_dyn_cur_1, l_pell_col_cnt_1, l_pell_desc_1);
    FOR l_pell_idx_1 IN 1 .. l_pell_col_cnt_1 LOOP
      IF l_pell_desc_1(l_pell_idx_1).col_type = 2 THEN
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_num_1);
      ELSIF l_pell_desc_1(l_pell_idx_1).col_type = 12 THEN
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_dt_1);
      ELSIF l_pell_desc_1(l_pell_idx_1).col_type IN (180, 181, 231) THEN
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_ts_1);
      ELSE
        DBMS_SQL.DEFINE_COLUMN(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_str_1, 4000);
      END IF;
    END LOOP;
    WHILE DBMS_SQL.FETCH_ROWS(l_pell_dyn_cur_1) > 0 LOOP
      l_pell_jobj_1 := NEW JSON_OBJECT_T();
      FOR l_pell_idx_1 IN 1 .. l_pell_col_cnt_1 LOOP
        l_pell_col_name_1 := l_pell_desc_1(l_pell_idx_1).col_name;
        IF l_pell_desc_1(l_pell_idx_1).col_type = 2 THEN
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_num_1);
          IF l_pell_buf_num_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, l_pell_buf_num_1); END IF;
        ELSIF l_pell_desc_1(l_pell_idx_1).col_type = 12 THEN
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_dt_1);
          IF l_pell_buf_dt_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, TO_CHAR(l_pell_buf_dt_1, 'YYYY-MM-DD"T"HH24:MI:SS')); END IF;
        ELSIF l_pell_desc_1(l_pell_idx_1).col_type IN (180, 181, 231) THEN
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_ts_1);
          IF l_pell_buf_ts_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, TO_CHAR(l_pell_buf_ts_1, 'YYYY-MM-DD"T"HH24:MI:SS.FF6')); END IF;
        ELSE
          DBMS_SQL.COLUMN_VALUE(l_pell_dyn_cur_1, l_pell_idx_1, l_pell_buf_str_1);
          IF l_pell_buf_str_1 IS NULL THEN l_pell_jobj_1.put_null(l_pell_col_name_1);
          ELSE l_pell_jobj_1.put(l_pell_col_name_1, l_pell_buf_str_1); END IF;
        END IF;
      END LOOP;
      l_pell_row_1 := l_pell_jobj_1.to_json();
      IF JSON_EXISTS(l_pell_row_1, '$.NAME') THEN
        l_saw := 1;
      END IF;
    END LOOP;
    DBMS_SQL.CLOSE_CURSOR(l_pell_dyn_cur_1);
    ut.expect(l_saw).to_equal(1);
  END t_source_stats;

