  PROCEDURE t_agg_library IS
    l_bor NUMBER;
    l_rng NUMBER;
    l_hm NUMBER;
    l_unq VARCHAR2(4000);
  BEGIN
    BEGIN
      select bitwise_or(column_value)
      INTO l_bor
      FROM table(sys.odcinumberlist(1, 2, 4));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_bor).to_equal(7);
    BEGIN
      select numeric_range(column_value)
      INTO l_rng
      FROM table(sys.odcinumberlist(3, 9, 5));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_rng).to_equal(6);
    BEGIN
      select round(harmonic_mean(column_value), 3)
      INTO l_hm
      FROM table(sys.odcinumberlist(1, 2, 4));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_hm).to_equal(1.714);
    BEGIN
      select unique_or_null(column_value)
      INTO l_unq
      FROM table(sys.odcivarchar2list('a', 'a'));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_unq).to_equal('a');
  END t_agg_library;

  PROCEDURE t_shapes_aggs IS
    l_tot NUMBER;
    l_cnt NUMBER;
  BEGIN
    BEGIN
      select total_amount(column_value)
      INTO l_tot
      FROM table(sys.odcinumberlist(10, 20, 30));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_tot).to_equal(60);
    BEGIN
      select sample_count(column_value)
      INTO l_cnt
      FROM table(sys.odcinumberlist(1, 2, 3));
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    ut.expect(l_cnt).to_equal(3);
  END t_shapes_aggs;
END ut_pell_examples;
